-- public.lamp_says(p_creature text, p_lamp text, p_was text, p_from text, p_now text, p_up boolean)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.lamp_says(p_creature text, p_lamp text, p_was text, p_from text, p_now text, p_up boolean)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case when p_was is not null
      then upper(left(p_lamp, 1)) || substr(p_lamp, 2) || ' used on ' || p_creature || ': ' || coalesce((select d.name from trait_def d where d.id = p_was), p_was)
        || ' (' || p_from || ') replaced by ' || lamp_kindled(p_now)
      else upper(left(p_lamp, 1)) || substr(p_lamp, 2) || ' used on ' || p_creature || ': ' || lamp_kindled(p_now) || ' added to an empty slot'
    end
    || case when p_up then ', a rarity above ' || p_from else '' end
    || '.'
    || case when not p_up and exists (select 1 from tier_odds t where t.ord > (select f.ord from tier_odds f where f.tier = p_from))
         then ' Rarity-up chance: 1 in ' || lamp_tier_odds()::int || '.' else '' end
$function$
